def _cgpt_process_pending_migrations():
    """ينقل العملاء المعلّقين (من حسابات ماتت) لما تتوفّr مقاعd."""
    try:
        pending = list(db.cgpt_pending_migration.find({'status': 'waiting'}))
    except Exception:
        return
    if not pending:
        return
    for pm in pending:
        email = pm.get('email')
        rem_min = pm.get('remaining_minutes', 0)
        if rem_min <= 0:
            db.cgpt_pending_migration.update_one({'_id': pm['_id']},
                {'$set': {'status': 'expired'}})
            continue
        target = _cgpt_find_available_account()
        if not target:
            return  # لا مقاعd بعd — ننتظر
        tgt_mgr = target['mgr']
        tgt_mgr._last_buyer_uid = pm.get('telegram_uid')
        res = tgt_mgr.invite_user(email, rem_min)
        if res.get('ok'):
            db.cgpt_pending_migration.update_one({'_id': pm['_id']},
                {'$set': {'status': 'migrated', 'to': target['email'],
                          'migrated_at': int(time.time())}})
            _CGPT_SEATS_CACHE['exp'] = 0
            # رسالة للعميل
            tg_uid = pm.get('telegram_uid')
            if tg_uid:
                try:
                    days = round(rem_min / 1440, 1)
                    bot.send_message(tg_uid,
                        f"🔄 <b>توفّر مقعd جديd — تم نقل اشتراكك!</b>\n\n"
                        f"📧 <b>الحساب الجديd:</b> <code>{html.escape(str(target['email']))}</code>\n"
                        f"⏳ <b>المتبقّي:</b> {days} يوم\n\n"
                        f"✅ وصلتك دعوة على بريدك — اقبلها لتكمل.",
                        parse_mode="HTML")
                except Exception:
                    pass
            # إشعm الأدمن
            try:
                for admin in db.users.find({'is_admin': 1}):
                    bot.send_message(admin['user_id'],
                        f"✅ نُقل معلّق: {email} → {target['email']}")
            except Exception:
                pass


def _cgpt_migrate_dead_account(dead_doc):
    """عند موت اشتراك حساب: ينقل عملاءه (الذين لهم مدة متبقية) لحساب حيّ.
    يرسل لكل عميل دعوة جديدة + رسالة، ويُشعر الأدمن."""
    dead_mgr = _cgpt_build_manager_from_doc(dead_doc)
    dead_email = dead_mgr.owner_email or dead_doc.get('name', 'حساب')
    now = _dt_mod.datetime.now()
    migrated = []
    failed = []
    # نجمع عملاء الحساب الميت الذين لهم مدة متبقية
    active_customers = []
    for email, info in dead_mgr.invites_data.get('invites', {}).items():
        if info.get('status') != 'active':
            continue
        try:
            exp = _dt_mod.datetime.fromisoformat(info['expires_at'])
            if exp > now:
                remaining_min = int((exp - now).total_seconds() / 60)
                active_customers.append((email, info, remaining_min))
        except Exception:
            pass
    if not active_customers:
        return  # لا عملاء للنقل
    for email, info, remaining_min in active_customers:
        # نجد حساباً حياً فيه مقعد فارغ
        target = _cgpt_find_available_account()
        if not target:
            failed.append(email)
            continue
        tgt_mgr = target['mgr']
        # لا ننقل لنفس الحساب الميت
        if getattr(tgt_mgr, '_account_key', '') == getattr(dead_mgr, '_account_key', ''):
            failed.append(email)
            continue
        tgt_mgr._last_buyer_uid = info.get('telegram_uid')
        res = tgt_mgr.invite_user(email, remaining_min)
        if res.get('ok'):
            migrated.append((email, target['email'], remaining_min))
            # نزيل من الحساب الميت
            dead_mgr.invites_data['invites'][email]['status'] = 'migrated'
            dead_mgr.invites_data['invites'][email]['migrated_to'] = target['email']
            # رسالة للعميل
            tg_uid = info.get('telegram_uid')
            if tg_uid:
                try:
                    days = round(remaining_min / 1440, 1)
                    bot.send_message(tg_uid,
                        f"🔄 <b>تم نقل اشتراكك لحساب جديد</b>\n\n"
                        f"📧 <b>الحساب الجديد:</b> <code>{html.escape(str(target['email']))}</code>\n"
                        f"⏳ <b>المدة المتبقية:</b> {days} يوم\n\n"
                        f"✅ <b>وصلتك دعوة جديدة على إيميلك</b> — اقبلها لتكمل اشتراكك.\n"
                        f"📩 تحقق من بريدك: <code>{html.escape(str(email))}</code>",
                        parse_mode="HTML")
                except Exception:
                    pass
        else:
            # لا مقعd متاح → نسجّله كـ "معلّق للنقل" (يُنقل لاحقاً تلقائياً)
            failed.append(email)
            try:
                db.cgpt_pending_migration.update_one(
                    {'email': email},
                    {'$set': {
                        'email': email,
                        'from_account': getattr(dead_mgr, '_account_key', ''),
                        'from_email': dead_email,
                        'remaining_minutes': remaining_min,
                        'telegram_uid': info.get('telegram_uid'),
                        'product_id': info.get('product_id', ''),
                        'created_at': int(time.time()),
                        'status': 'waiting'
                    }}, upsert=True)
            except Exception:
                pass
    dead_mgr._save_data()
    # إشعار الأدمن
    lines = [f"🔄 <b>نقل تلقائي — حساب مات</b>\n"]
    lines.append(f"💀 الحساب الميت: <code>{html.escape(str(dead_email))}</code>\n")
    if migrated:
        lines.append(f"✅ <b>نُقل ({len(migrated)}):</b>")
        for em, to, rem in migrated[:15]:
            lines.append(f"  • <code>{em}</code> → {to} ({round(rem/1440,1)}ي)")
    if failed:
        lines.append(f"\n⚠️ <b>تعذّر نقلهم ({len(failed)}) — لا مقاعد فارغة:</b>")
        for em in failed[:15]:
            lines.append(f"  • <code>{em}</code>")
        lines.append("\n<i>أضف حساباً جديداً فيه مقاعد فارغة.</i>")
    try:
        for admin in db.users.find({'is_admin': 1}):
            try: bot.send_message(admin['user_id'], "\n".join(lines), parse_mode="HTML")
            except Exception: pass
        bot.send_message(OWNER_ID, "\n".join(lines), parse_mode="HTML")
    except Exception:
        pass


_CGPT_SEATS_CACHE = {'val': None, 'exp': 0}


