@bot.message_handler(
    func=lambda m: _check_locked(m.from_user.id)
)
def _deposit_lock_guard_message(message):
    uid=message.from_user.id
    if (message.text or '').strip() in ('/cancel','cancel','إلغاء','الغاء'):
        from ton_payments import NS_call
        return cancel_deposit_handler(NS_call(message))
    pending=db.pending_deposits.find_one({'user_id':uid,'coin':'TON','status':'pending','expires_at':{'$gt':int(time.time())}})
    if pending and message.text and not message.text.startswith('/'):
        return verify_ton_public_blockchain(message,get_lang(uid),get_setting('ton_address'))
    send_payment_lock_warning(uid)



# 🛡 دالة فحص صلاحية الأدمن (تُستخدم بكل دوال الأدمن)
def _is_admin_check(uid):
    """يتحقق إن المستخدم أدمن أو OWNER"""
    if uid == OWNER_ID:
        return True
    try:
        u = db.users.find_one({'user_id': int(uid)})
        return u and u.get('is_admin') == 1
    except Exception:
        return False


# 🛡 Middleware: يفحص كل callback queries اللي تبدأ بـ ad_ أو admin_
# لو المستخدم مو أدمن، يرفض الطلب فوراً قبل ما يصير أي شي
def _admin_only_middleware(call):
    """
    🛡 فحص أمني: يرفض أي محاولة وصول لدوال الأدمن من غير الأدمن.
    """
    if not call.data:
        return True  # ما فيه callback data - نسمح (مو دالة admin)
    
    # الـ callbacks المحمية
    is_admin_callback = (
        call.data.startswith('ad_') or 
        call.data.startswith('admin_') or
        call.data.startswith('edit_txt_') or
        call.data.startswith('toggle_amount_protection')
    )
    
    if not is_admin_callback:
        return True  # مو callback admin - نسمح
    
    # نشيك صلاحية المستخدم
    uid = call.from_user.id
    if _is_admin_check(uid):
        return True  # admin - مسموح
    
    # 🚨 محاولة وصول غير مصرح بها!
    try:
        bot.answer_callback_query(
            call.id, 
            bil(uid, "❌ ليس لديك صلاحية للوصول لهذه القائمة!", "❌ You don't have permission to access this menu!"),
            show_alert=True
        )
    except Exception:
        pass
    
    # نسجل المحاولة
    try:
        db.unauthorized_attempts.insert_one({
            'user_id': uid,
            'username': call.from_user.username or 'unknown',
            'callback_data': call.data[:200],
            'timestamp': int(time.time())
        })
    except Exception:
        pass
    
    logger.warning(f"🚨 محاولة وصول غير مصرح بها: المستخدم {uid} حاول {call.data}")
    return False  # رفض المعالجة


def admin_required(func):
    """
    🛡 Decorator يحمي دوال الأدمن من الوصول غير المصرح به.
    
    استخدامها:
    @admin_required
    def my_admin_function(call):
        ...
    """
    def wrapper(call, *args, **kwargs):
        uid = call.from_user.id
        if not _is_admin_check(uid):
            try:
                bot.answer_callback_query(
                    call.id,
                    bil(uid, "❌ ليس لديك صلاحية!", "❌ You don't have permission!"),
                    show_alert=True
                )
            except Exception:
                pass
            
            # نسجل المحاولة
            try:
                db.unauthorized_attempts.insert_one({
                    'user_id': uid,
                    'username': getattr(call.from_user, 'username', 'unknown') or 'unknown',
                    'callback_data': str(call.data)[:200] if hasattr(call, 'data') else 'message',
                    'timestamp': int(time.time())
                })
            except Exception:
                pass
            
            logger.warning(f"🚨 محاولة وصول غير مصرح بها: المستخدم {uid}")
            return
        return func(call, *args, **kwargs)
    
    wrapper.__name__ = func.__name__
    return wrapper

logger.info("⏳ جاري الاتصال بقاعدة البيانات MongoDB...")
try:
    mongo_client = MongoClient(MONGO_URI, serverSelectionTimeoutMS=5000)
    mongo_client.server_info()
    db = mongo_client[MONGO_DB_NAME] 
    logger.info("✅ تم الاتصال بقاعدة البيانات بنجاح!")
    # ⚡ فهارس الأداء الحرجة — تُنشأ في كل إقلاع (idempotent، آمنة للتكرار)
    #    بدونها كل استعلام يمسح المجموعة كاملة → بطء شديد في عرض القائمة.
    try:
        db.products.create_index('id', background=True)
        db.product_stock.create_index('product_id', background=True)
        db.product_stock.create_index([('product_id', 1), ('is_sold', 1)], background=True)
        db.pending_deposits.create_index([('coin', 1), ('status', 1)], background=True)
        db.catalogs.create_index('order', background=True)
        db.ext_products.create_index('store_id', background=True)
        db.ext_products.create_index('hidden', background=True)
        db.ext_orders.create_index('store_id', background=True)
        db.ext_pending_new.create_index([('store_id', 1), ('ext_id', 1)], background=True)
        logger.info("✅ فهارس الأداء جاهزة")
    except Exception as _idx_e:
        logger.debug(f"perf index info: {_idx_e}")
except Exception as e:
    logger.error(f"❌ خطأ حرج في MongoDB: {e}")
    sys.exit(1)

