# 🛠️ 7. محرك الـ CMS (ترجمة آمنة مع حماية الرموز التعبيرية)
# ============================================================

def translate_duration_label(label, target_lang='en'):
    if not label:
        return label
    if target_lang != 'en':
        return label
    
    label_str = str(label).strip()
    # Check if already English/numbers only
    if re.match(r'^[a-zA-Z0-9\s\-\.\_\(\)]+$', label_str):
        return label_str

    words_map = {
        'أيام': 'Days',
        'ايام': 'Days',
        'يوم': 'Day',
        'شهور': 'Months',
        'أشهر': 'Months',
        'اشهر': 'Months',
        'شهر': 'Month',
        'سنوات': 'Years',
        'سنة': 'Year',
        'عام': 'Year',
        'أعوام': 'Years',
        'اعوام': 'Years',
        'ساعات': 'Hours',
        'ساعة': 'Hour',
        'أسبوع': 'Week',
        'اسبوع': 'Week',
        'أسابيع': 'Weeks',
        'اسابيع': 'Weeks',
        'تلقائي': 'Auto',
        'فوري': 'Instant',
        'مدى الحياة': 'Lifetime',
        'مفتوح': 'Unlimited',
    }

    # Match number(s) + spaces + word
    match = re.match(r'^(\d+)\s+(.+)$', label_str)
    if match:
        num = match.group(1)
        term = match.group(2).strip()
        if term in words_map:
            return f"{num} {words_map[term]}"

    # Try exact match
    if label_str in words_map:
        return words_map[label_str]

    res = label_str
    for ar_w, en_w in words_map.items():
        res = re.sub(rf'\b{ar_w}\b', en_w, res)
        res = res.replace(ar_w, en_w)

    if re.search(r'[\u0600-\u06FF]', res):
        try:
            translated = safe_translate_for_cms(label_str, 'en')
            if translated and translated != label_str:
                return translated
        except:
            pass

    return res

def get_translated_product_name(p, lang, is_cgpt=False):
    if not p:
        return "Unknown Product"
    
    if lang == 'en':
        n = p.get('name_en') or p.get('name' if is_cgpt else 'name_ar', '')
        if not n:
            n = "Product"
        # لو الاسم عربي ولا يوجد name_en مخزّن: نعرض المتوفّر فوراً (بلا انتظار)
        # ونترجمه في الخلفية للمرّات القادمة — الترجمة المتزامنة كانت تعلّق القائمة.
        if re.search(r'[\u0600-\u06FF]', n) and not p.get('_name_en_pending'):
            try:
                _pid = p['_id']
                _coll = 'cgpt_products' if is_cgpt else 'products'
                def _bg_translate(pid=_pid, coll=_coll, src=n):
                    try:
                        tr = safe_translate_for_cms(src, 'en')
                        if tr and tr != src and not re.search(r'[\u0600-\u06FF]', tr):
                            db[coll].update_one({'_id': pid}, {'$set': {'name_en': tr}})
                    except Exception:
                        pass
                threading.Thread(target=_bg_translate, daemon=True).start()
            except Exception:
                pass
        return n
    else:
        n = p.get('name' if is_cgpt else 'name_ar') or p.get('name_en', '')
        if not n:
            n = "بدون اسم"
        return n

def get_translated_product_desc(p, lang, is_cgpt=False):
    if not p:
        return ""
    if lang == 'en':
        d = p.get('desc_en') or p.get('desc' if is_cgpt else 'desc_ar', '')
        # ترجمة في الخلفية (لا تعليق للعرض)
        if d and re.search(r'[\u0600-\u06FF]', d):
            try:
                _pid = p['_id']
                _coll = 'cgpt_products' if is_cgpt else 'products'
                def _bg_translate_desc(pid=_pid, coll=_coll, src=d):
                    try:
                        tr = safe_translate_for_cms(src, 'en')
                        if tr and tr != src and not re.search(r'[\u0600-\u06FF]', tr):
                            db[coll].update_one({'_id': pid}, {'$set': {'desc_en': tr}})
                    except Exception:
                        pass
                threading.Thread(target=_bg_translate_desc, daemon=True).start()
            except Exception:
                pass
        return d
    else:
        return p.get('desc' if is_cgpt else 'desc_ar') or p.get('desc_en', '')

def clean_old_emojis(text):
    old_emojis = ['🛒', '💳', '👤', '👥', '👨‍💻', '🌐', '👑', '⭐️', '🟡', '🟢', '💎', '🔵', '🔴', '🛍', '📄', '🎓', '✨', '🔄', '🏠', '🔙', '✅', '📦', '✏️', '🎛', '📝', '🚚', '💰', '📊', '📉', '🔔']
    for emj in old_emojis:
        text = text.replace(emj, '')
    return text.strip()

def safe_translate_for_cms(text, target_lang='en'):
    """
    ترجمة آمنة تحافظ على:
    - Premium Emojis (<tg-emoji>)
    - HTML tags (<b>, <i>, <code>, <blockquote>, etc.)
    - Placeholders {} و {name}
    - URLs
    - الإيموجيات العادية
    - 🆕 الأسطر الجديدة والمسافات الفارغة (التنسيق البصري)
    """
    if not text or not text.strip():
        return text
    
    try:
        # 🆕 الاستراتيجية الجديدة: نترجم سطر بسطر
        # هذا يحافظ على كل الفواصل والأسطر الفارغة بالضبط
        lines = text.split('\n')
        translated_lines = []
        
        for line in lines:
            # 🛡 الأسطر الفارغة نتركها كما هي
            if not line.strip():
                translated_lines.append(line)  # سطر فارغ يبقى فارغ
                continue
            
            # 🛡 الأسطر اللي فيها بس فواصل بصرية (━━━ أو ─── أو ═══) نتركها
            if re.match(r'^[━─═\s]+$', line):
                translated_lines.append(line)
                continue
            
            # 🛡 لو السطر بدون أي نص قابل للترجمة (بس HTML tags + رموز)
            # نتحقق إن فيه أي حرف عربي أو إنجليزي حقيقي
            text_only = re.sub(r'<[^>]+>', '', line)  # احذف HTML
            text_only = re.sub(r'<tg-emoji[^>]*>.*?</tg-emoji>', '', text_only, flags=re.DOTALL)
            text_only = re.sub(r'\{[^}]*\}', '', text_only)  # احذف placeholders
            text_only = re.sub(r'https?://\S+', '', text_only)  # احذف URLs
            text_only = re.sub(r'[━─═]+', '', text_only)  # احذف فواصل
            
            # لو ما بقي حروف أو أرقام عربية/إنجليزية، نتركها كما هي
            if not re.search(r'[a-zA-Z\u0600-\u06FF\u0750-\u077F]', text_only):
                translated_lines.append(line)
                continue
            
            # 🌐 نترجم السطر مع حماية كل العناصر الحساسة
            translated_line = _translate_single_line(line, target_lang)
            translated_lines.append(translated_line)
        
        # 🛡 نجمع الأسطر كما كانت بالضبط (مع كل الـ \n)
        result = '\n'.join(translated_lines)
        
        # 🛡 فحص نهائي للسلامة
        # 1. عدد {} placeholders (هذا الفحص صارم - مهم)
        original_placeholders = len(re.findall(r'\{[^}]*\}', text))
        translated_placeholders = len(re.findall(r'\{[^}]*\}', result))
        if original_placeholders != translated_placeholders:
            logger.warning(
                f"⚠️ Translation lost placeholders! "
                f"Original: {original_placeholders}, Translated: {translated_placeholders}. "
                f"Returning original text."
            )
            return text
        
        # 2. عدد <tg-emoji> (هذا الفحص صارم - مهم للإيموجي المميز)
        original_emojis = len(re.findall(r'<tg-emoji', text))
        translated_emojis = len(re.findall(r'<tg-emoji', result))
        if original_emojis != translated_emojis:
            logger.warning(
                f"⚠️ Translation lost premium emojis! "
                f"Original: {original_emojis}, Translated: {translated_emojis}. "
                f"Trying to fix by appending missing emojis..."
            )
            # 🆕 لو فقدنا إيموجيات، نحاول نضيفها في نهاية النص بدل ما نرفض الترجمة كاملاً
            try:
                # نجلب كل tg-emoji tags من النص الأصلي
                original_emoji_tags = re.findall(r'<tg-emoji[^>]*>.*?</tg-emoji>', text, re.DOTALL)
                translated_emoji_set = set(re.findall(r'<tg-emoji[^>]*>.*?</tg-emoji>', result, re.DOTALL))
                
                # نضيف اللي مفقود في نهاية النص
                missing_emojis = []
                for emoji_tag in original_emoji_tags:
                    if emoji_tag not in translated_emoji_set:
                        missing_emojis.append(emoji_tag)
                
                if missing_emojis:
                    result = result + ' ' + ' '.join(missing_emojis)
                    logger.info(f"✅ Recovered {len(missing_emojis)} missing emojis")
            except Exception as fix_err:
                logger.error(f"Failed to recover emojis: {fix_err}")
                return text
        
        # 3. HTML tags متوازنة (هذا الفحص أصبح تحذيري فقط - مو يرفض الترجمة)
        unbalanced_tags = []
        for tag in ['b', 'i', 'u', 's', 'code', 'blockquote', 'pre']:
            open_count = len(re.findall(rf'<{tag}[^>]*>', result, re.IGNORECASE))
            close_count = len(re.findall(rf'</{tag}>', result, re.IGNORECASE))
            if open_count != close_count:
                unbalanced_tags.append(f"<{tag}>")
                # نحاول نصلح: نضيف tags إغلاق ناقصة في النهاية
                if open_count > close_count:
                    diff = open_count - close_count
                    result = result + (f'</{tag}>' * diff)
                elif close_count > open_count:
                    diff = close_count - open_count
                    result = (f'<{tag}>' * diff) + result
        
        if unbalanced_tags:
            logger.warning(f"⚠️ Fixed unbalanced tags: {unbalanced_tags}")
        
        return result
    except Exception as e:
        logger.error(f"Safe translation error: {e}")
        return text


# ============================================================
# 🌐 الترجمة بالتقسيم — الطريقة الموثوقة
# ============================================================
# المشكلة في الطريقة القديمة: كانت تستبدل الوسوم والمتغيّرات برموز (XQ0QX)
# وترسل كل شيء لجوجل. جوجل يمزّق الرموز أحياناً → تفشل الترجمة ويرجع النص عربياً.
#
# الطريقة الصحيحة: لا نرسل الوسوم/المتغيّرات لجوجل إطلاقاً.
# نقسّم السطر لأجزاء، نترجم النص الخالص فقط، ثم نعيد التركيب بالترتيب.
# النتيجة: يستحيل ضياع متغيّر أو وسم، والترجمة تنجح دائماً.

# كل ما يجب الحفاظ عليه حرفياً (لا يُرسل للمترجم أبداً)
_PRESERVE_RE = re.compile(
    r'(<tg-emoji[^>]*>.*?</tg-emoji>'          # إيموجي بريميوم
    r'|<code>.*?</code>|<pre>.*?</pre>'         # كتل الكود
    r'|https?://[^\s<>"]+'                      # روابط
    r'|\{[^}]*\}'                               # متغيّرات {0} {name}
    r'|</?[a-zA-Z][^>]*>'                       # وسوم HTML
    r'|[━─═]{2,}'                               # فواصل بصرية
    r'|[0-9#*]\ufe0f?\u20e3'                    # أرقام مؤطّرة 1️⃣2️⃣3️⃣
    r'|[\u2600-\u27BF\U0001F000-\U0001F9FF\U0001FA00-\U0001FAFF\u200d\ufe0f]+'  # إيموجي عادي
    r')',
    re.DOTALL
)


# علامات تدل أن "الترجمة" في الحقيقة صفحة خطأ من الخادم
_BAD_TR_MARKERS = (
    "error 500", "error 502", "error 503", "server error",
    "that's an error", "that\u2019s an error",
    "that's all we know", "that\u2019s all we know",
    "please try again later", "bad gateway", "service unavailable",
    "<html", "<!doctype", "429 (too many requests", "404 (not found",
)


def _is_bad_translation(src_text, result):
    """يكشف الردود الفاسدة (صفحات خطأ / محتوى غريب) قبل إدخالها في نص المستخدم.

    ⚠️ سبب وجودها: مكتبة الترجمة قد ترجع محتوى صفحة خطأ HTTP كأنه ترجمة،
    فيظهر للمستخدم نص مثل "Error 500 (Server Error)!!1..." داخل رسالته.
    """
    if not result or not str(result).strip():
        return True
    r = str(result)
    low = r.lower()
    if any(m in low for m in _BAD_TR_MARKERS):
        return True
    # رد أطول بشكل غير معقول من المصدر ⇒ شبه مؤكد صفحة خطأ
    if len(r) > max(len(src_text) * 6, len(src_text) + 120):
        return True
    return False


def _translate_text_raw(text, target_lang, tries=1):
    """يترجم نصاً. مهم: مهلة قصيرة جداً ومحاولة واحدة فقط لتجنّب تعليق الواجهة.
    لو الترجمة فشلت، نرجّع None فوراً ويُستخدم النص الأصلي — أفضل من تعليق 30 ثانية."""
    _warned = False
    # محاولة واحدة سريعة فقط (لا تكرار، لا بروكسيات بطيئة)
    try:
        r = GoogleTranslator(source='auto', target=target_lang).translate(text)
        if r and not _is_bad_translation(text, r):
            return str(r)
        if r and not _warned:
            logger.warning(f"translate: bad response rejected ({str(r)[:60]!r})")
    except Exception as e:
        logger.debug(f"translate direct err: {e}")
    # مزود احتياطي: Render قد يتلقى حظراً مؤقتاً من Google Translate.
    try:
        source_lang = 'ar' if target_lang == 'en' else 'en'
        r = MyMemoryTranslator(source=source_lang, target=target_lang).translate(text=text)
        if r and not _is_bad_translation(text, r):
            return str(r)
    except Exception as e:
        logger.debug(f"translate fallback err: {e}")
    # لا بروكسيات بطيئة — نرجّع None ويحتفظ المستدعي بالنص الأصلي.
    return None


def _translate_single_line(line, target_lang='en'):
    """يترجم سطراً واحداً بطريقة التقسيم (الوسوم والمتغيّرات لا تُرسل للمترجم)."""
    if not line or not line.strip():
        return line
    try:
        parts = _PRESERVE_RE.split(line)
        out = []
        for p in parts:
            if not p:
                continue
            # جزء محمي → يُنسخ كما هو
            if _PRESERVE_RE.fullmatch(p):
                out.append(p)
                continue
            # لا يحوي حروفاً → مسافات/ترقيم فقط
            if not re.search(r'[a-zA-Z\u0600-\u06FF\u0750-\u077F]', p):
                out.append(p)
                continue
            # نص خالص → نترجمه وحده (نحافظ على المسافات الطرفية)
            lead = p[:len(p) - len(p.lstrip())]
            trail = p[len(p.rstrip()):]
            core = p.strip()
            tr = _translate_text_raw(core, target_lang)
            out.append(lead + (tr if tr else core) + trail)
        result = ''.join(out)

        # 🛡 حارس أخير: لو تسلّل محتوى صفحة خطأ إلى الناتج، نرفضه كلياً
        if any(m in result.lower() for m in _BAD_TR_MARKERS):
            logger.warning("segment translate: error-page content detected — keeping original")
            return line

        # 🛡 تحقق نهائي: الوسوم والمتغيّرات لازم تبقى كما هي بالضبط
        if len(re.findall(r'\{[^}]*\}', result)) != len(re.findall(r'\{[^}]*\}', line)):
            logger.warning("segment translate: placeholder mismatch — keeping original")
            return line
        if len(re.findall(r'<tg-emoji', result)) != len(re.findall(r'<tg-emoji', line)):
            logger.warning("segment translate: tg-emoji mismatch — keeping original")
            return line
        return result
    except Exception as e:
        logger.debug(f"segment translate error: {e}")
        return line


def _translate_line_core(line, target_lang='en', protect_html=True):
    """
    يترجم سطر واحد مع حفظ كامل لـ:
    - Premium Emojis <tg-emoji> (بالترقيم الموضعي الآمن)
    - HTML tags <b><i><code> إلخ
    - Placeholders {}
    - URLs
    - إيموجي عادية
    
    الاستراتيجية: نفصل كل عنصر محمي ونضعه في قاموس بـ UUID ثابت لا يتغير بالترجمة.
    """
    try:
        # 🔑 رموز حماية قصيرة ومرقّمة (XQ0QX) بدل UUID عشوائي طويل (XPROTX+8):
        #    المترجم يمزّق الرموز الطويلة العشوائية كثيراً → يضيع العنصر المحمي،
        #    وأشهر عرض لهذا: اختفاء <tg-emoji> ثم إلغاء الترجمة بالكامل
        #    (تحذير: tg-emoji count mismatch → returning original).
        vault = {}          # key → (نوع العنصر، النص الأصلي)
        _seq = [0]

        def protect_item(text_to_protect, kind='other'):
            idx = _seq[0]; _seq[0] += 1
            key = f"XQ{idx}QX"
            vault[key] = (kind, text_to_protect)
            return f" {key} "
        
        temp = line
        
        # 1. Premium Emojis — أعلى أولوية (قبل أي شيء)
        temp = re.sub(
            r'<tg-emoji[^>]*>.*?</tg-emoji>',
            lambda m: protect_item(m.group(0), 'tg_emoji'),
            temp,
            flags=re.DOTALL
        )
        
        # 2. Code/Pre blocks
        temp = re.sub(r'<code>.*?</code>', lambda m: protect_item(m.group(0), 'html'), temp, flags=re.DOTALL)
        temp = re.sub(r'<pre>.*?</pre>', lambda m: protect_item(m.group(0), 'html'), temp, flags=re.DOTALL)
        
        # 3. URLs
        temp = re.sub(r'https?://[^\s<>"]+', lambda m: protect_item(m.group(0), 'url'), temp)
        
        # 4. Placeholders
        temp = re.sub(r'\{[^}]*\}', lambda m: protect_item(m.group(0), 'placeholder'), temp)
        
        # 5. فواصل بصرية
        temp = re.sub(r'[━─═]{2,}', lambda m: protect_item(m.group(0), 'deco'), temp)
        
        # 6. HTML tags (نحمي فقط الـ tags، محتواها يُترجم)
        #    عند إعادة المحاولة نتركها بلا حماية: جوجل يحافظ على <b>/<i> عادةً،
        #    وتقليل عدد الرموز يرفع نسبة نجاح الترجمة كثيراً.
        if protect_html:
            temp = re.sub(r'</?[a-zA-Z][^>]*>', lambda m: protect_item(m.group(0), 'html'), temp)
        
        # 7. إيموجي عادية
        emoji_pat = re.compile(
            r"[\u2600-\u27BF\U0001F000-\U0001F9FF\U0001FA00-\U0001FAFF\u200d\ufe0f]+",
            flags=re.UNICODE
        )
        temp = emoji_pat.sub(lambda m: protect_item(m.group(0), 'emoji'), temp)
        
        # تحقق: لو ما بقي نص حقيقي
        clean_check = re.sub(r'(?i)XQ\d{1,3}QX', '', temp).strip()
        if not clean_check or len(clean_check) < 2:
            return line
        
        # 🌐 الترجمة
        translated = None
        import requests
        original_get = requests.get
        def patched_get(*args, **kwargs):
            kwargs['timeout'] = 4.0  # 4 seconds timeout
            return original_get(*args, **kwargs)
            
        requests.get = patched_get
        try:
            try:
                translated = GoogleTranslator(source='auto', target=target_lang).translate(temp)
            except Exception as e:
                logger.warning(f"Direct translation failed: {e}. Retrying with proxies...")
                
            if not translated:
                proxies_to_try = list(VERIFIED_PROXIES)
                if proxies_to_try:
                    random.shuffle(proxies_to_try)
                    for proxy in proxies_to_try[:5]:
                        try:
                            translated = GoogleTranslator(
                                source='auto',
                                target=target_lang,
                                proxies={'http': proxy, 'https': proxy}
                            ).translate(temp)
                            if translated:
                                logger.info(f"Translation succeeded using proxy: {proxy}")
                                break
                        except Exception as proxy_err:
                            logger.debug(f"Translation proxy {proxy} failed: {proxy_err}")
        finally:
            requests.get = original_get
            
        if not translated:
            return line
        
        # 🔁 تطبيع المفاتيح: المترجم قد يضيف مسافات أو يغيّر حالة الأحرف (x q 0 q x)
        translated = re.sub(
            r'(?i)x\s*q\s*(\d{1,3})\s*q\s*x',
            lambda m: f"XQ{m.group(1)}QX",
            translated
        )
        
        # 🔁 استرجاع العناصر المحمية
        for key, (_kind, original) in vault.items():
            translated = re.sub(re.escape(key), lambda m, _o=original: _o, translated, flags=re.IGNORECASE)
        
        # 🧹 نظّف أي مفتاح مشوّه لم يُسترجع (نعالج فقدان محتواه بالأسفل)
        translated = re.sub(r'(?i)X\s*Q\s*\d{1,3}\s*Q\s*X', '', translated)
        
        # 🛠 استرجاع ذكي: بدل إلغاء الترجمة كلياً عند ضياع عنصر،
        #    نعيد إدراج ما يمكن إدراجه بأمان (الأيقونات)، ونلغي فقط عند ضياع
        #    عنصر لا يجوز تخمين مكانه (وسم HTML / رابط / placeholder).
        missing_critical = False
        missing_tg = []
        missing_emoji = []
        for _key, (_kind, _orig) in vault.items():
            if not _orig or _orig in translated:
                continue
            if _kind == 'tg_emoji':
                missing_tg.append(_orig)
            elif _kind == 'emoji':
                missing_emoji.append(_orig)
            elif _kind == 'deco':
                pass  # فواصل بصرية: فقدانها غير مؤثر
            else:
                missing_critical = True
        
        if missing_critical:
            logger.warning("protected tag/url lost in translation - returning original line")
            return line
        
        # نعيد الأيقونات المفقودة: tg-emoji للبداية (مكانها الطبيعي)، والعادية للنهاية
        if missing_tg or missing_emoji:
            _body = translated.strip()
            if missing_tg:
                _body = ''.join(missing_tg) + (' ' + _body if _body else '')
            if missing_emoji:
                _body = (_body + ' ' if _body else '') + ''.join(missing_emoji)
            translated = _body
            logger.info(
                f"recovered lost icons after translation "
                f"(tg-emoji: {len(missing_tg)}, emoji: {len(missing_emoji)})"
            )
        
        # 🧽 تنظيف المسافات الزائدة الناتجة عن حشو الرموز (" KEY ")
        translated = re.sub(r'[ \t]{2,}', ' ', translated)
        translated = re.sub(r'(<[a-zA-Z][^>]*>) +', r'\1', translated)   # <b> نص  →  <b>نص
        translated = re.sub(r' +(</[a-zA-Z][^>]*>)', r'\1', translated)  # نص </b>  →  نص</b>
        
        # 🛡 فحص نهائي: عدد tg-emoji لازم يكون نفسه
        orig_tg = len(re.findall(r'<tg-emoji', line))
        result_tg = len(re.findall(r'<tg-emoji', translated))
        if orig_tg != result_tg:
            logger.warning(f"tg-emoji count mismatch after translation ({orig_tg} vs {result_tg}) - returning original")
            return line
        
        return translated.strip()
    except Exception as e:
        logger.debug(f"Single line translation error: {e}")
        return line


def extract_custom_emojis_to_html(message):
    if not message.text or not message.entities:
        return message.text or ""
    
    text = message.text
    entities = sorted([e for e in message.entities if e.type == 'custom_emoji'], key=lambda x: x.offset, reverse=True)
    
    encoded_text = text.encode('utf-16-le')
    for ent in entities:
        start = ent.offset * 2
        end = start + (ent.length * 2)
        emoji_char = encoded_text[start:end].decode('utf-16-le')
        html_emoji = f'<tg-emoji emoji-id="{ent.custom_emoji_id}">{emoji_char}</tg-emoji>'
        encoded_text = encoded_text[:start] + html_emoji.encode('utf-16-le') + encoded_text[end:]
        
    return encoded_text.decode('utf-16-le')

def parse_button_input(message):
    text = message.text
    emoji_id = None
    if message.entities:
        for ent in message.entities:
            if ent.type == 'custom_emoji':
                emoji_id = ent.custom_emoji_id
                emoji_char = message.text[ent.offset:ent.offset+ent.length]
                text = text.replace(emoji_char, '', 1) 
                break
    text = clean_old_emojis(text)
    return text.strip(), emoji_id

_CUSTOM_TEXTS_CACHE = {}      # {(lang, key): value}
_CUSTOM_TEXTS_LOADED = [False]


def _load_custom_texts_cache():
    """يحمّل كل النصوص المخصّصة مرة واحدة للذاكرة (بدل استعلام لكل get_text)."""
    try:
        cache = {}
        for row in db.custom_texts.find({}):
            k = (row.get('lang'), row.get('key'))
            v = row.get('value')
            if k[0] and k[1] and v:
                cache[k] = v
        _CUSTOM_TEXTS_CACHE.clear()
        _CUSTOM_TEXTS_CACHE.update(cache)
        _CUSTOM_TEXTS_LOADED[0] = True
    except Exception as e:
        logger.debug(f"load custom_texts cache err: {e}")


def _invalidate_custom_texts_cache():
    """يعيد تحميل النصوص المخصّصة (بعد أي تعديل من الأدمن)."""
    _CUSTOM_TEXTS_LOADED[0] = False


def get_text(uid, key, *args):
    l = get_lang(uid)
    if l not in ['ar', 'en']:
        l = 'ar'

    # نحفظ النص الافتراضي من الكود كـ backup
    default_text = LANG.get(l, LANG['ar']).get(key, "")

    base_text = ""
    custom_text_used = False

    # ⚡ نقرأ من الذاكرة بدل استعلام DB لكل نص
    if not _CUSTOM_TEXTS_LOADED[0]:
        _load_custom_texts_cache()
    try:
        cached_val = _CUSTOM_TEXTS_CACHE.get((l, key))
        if cached_val and cached_val.strip():
            base_text = cached_val
            custom_text_used = True
        else:
            base_text = default_text
    except Exception as e:
        logger.debug(f"get_text cache error: {e}")
        base_text = default_text
    
    if not base_text:
        base_text = LANG.get('ar', {}).get(key, "") or LANG.get('en', {}).get(key, "")
    
    if args:
        # 🛡 محاولة الـ format على النص الحالي
        try:
            return base_text.format(*args)
        except Exception as e:
            # ❌ الـ format فشلت — غالباً النص المخصص فقد بعض الـ {} placeholders
            # 🔄 fallback: نستخدم النص الافتراضي من الكود
            logger.warning(
                f"⚠️ Custom text for key '{key}' (lang={l}) has broken placeholders. "
                f"Falling back to default text. Error: {e}"
            )
            
            if custom_text_used and default_text:
                try:
                    # 🛡 محاولة بالنص الافتراضي
                    return default_text.format(*args)
                except Exception as e2:
                    logger.error(f"Even default text failed for key '{key}': {e2}")
                    return default_text
            
            # آخر شي: نرجع النص بدون format (أحسن من رسالة فاضية)
            return base_text
    
    return base_text

def get_btn_data(uid, key):
    l = get_lang(uid)
    if l not in ['ar', 'en']:
        l = 'ar'
    
    try:
        custom = db.custom_buttons.find_one({'lang': l, 'key': key})
        if custom:
            text = custom.get('text', '').strip()
            emoji_id = custom.get('emoji_id', None)
            if not text:
                default_text = DEFAULT_BUTTONS.get(l, DEFAULT_BUTTONS['ar']).get(key, key)
                return default_text, emoji_id
            return text, emoji_id
    except Exception as e:
        logger.error(f"get_btn_data DB error: {e}")
    
    default_text = DEFAULT_BUTTONS.get(l, DEFAULT_BUTTONS['ar']).get(key, key)
    return default_text, None

def create_btn(uid, key, callback_data=None, url=None, style=None):
    text, emj_id = get_btn_data(uid, key)
    # 🆕 لو ما في style override، نجيبها من DB (Bot API 9.4: danger/success/primary)
    if style is None:
        try:
            l = get_lang(uid) if get_lang(uid) in ['ar', 'en'] else 'ar'
            custom = db.custom_buttons.find_one({'lang': l, 'key': key})
            if custom and custom.get('style'):
                style = custom['style']
        except Exception: pass
    kwargs = {'text': text}
    if callback_data: kwargs['callback_data'] = callback_data
    if url: kwargs['url'] = url
    if style: kwargs['style'] = style
    if emj_id: kwargs['icon_custom_emoji_id'] = emj_id
    return CustomInlineButton(**kwargs)

