_PRODUCTS_LIST_CACHE = {'data': None, 'exp': 0}
_PRODUCTS_BY_ID_CACHE = {'map': {}, 'exp': 0}
_PRODUCTS_CACHE_TTL = 60  # ثانية


def _get_all_products_cached():
    """يجلب كل المنتجات مرة كل 60 ثانية (بدل استعلام لكل مستخدم)."""
    now = time.time()
    if _PRODUCTS_LIST_CACHE['data'] is not None and _PRODUCTS_LIST_CACHE['exp'] > now:
        return _PRODUCTS_LIST_CACHE['data']
    try:
        data = list(db.products.find())
    except Exception:
        return _PRODUCTS_LIST_CACHE['data'] or []
    _PRODUCTS_LIST_CACHE['data'] = data
    _PRODUCTS_LIST_CACHE['exp'] = now + _PRODUCTS_CACHE_TTL
    # نبني خريطة id→product للبحث السريع (find_product)
    idmap = {}
    for p in data:
        pid = p.get('id')
        if pid is not None:
            idmap[str(pid)] = p
        idmap[str(p.get('_id'))] = p
    _PRODUCTS_BY_ID_CACHE['map'] = idmap
    _PRODUCTS_BY_ID_CACHE['exp'] = now + _PRODUCTS_CACHE_TTL
    return data


def _invalidate_products_cache():
    """يمسح cache المنتجات (بعد أي إضافة/تعديل/حذف)."""
    _PRODUCTS_LIST_CACHE['data'] = None
    _PRODUCTS_LIST_CACHE['exp'] = 0
    _PRODUCTS_BY_ID_CACHE['map'] = {}
    _PRODUCTS_BY_ID_CACHE['exp'] = 0
    globals()['_PRODUCTS_CACHE'] = None


def find_product(pid):
    return _find_product_db(pid)


def _find_product_db(pid):
    pid_str = str(pid)
    try:
        # ── 1. بحث بـ id field (الأكثر شيوعاً) ──
        p = db.products.find_one({'id': pid_str})
        if p: return p
        if pid_str.isdigit():
            p = db.products.find_one({'id': int(pid_str)})
            if p: return p
        try:
            p = db.products.find_one({'id': finite_float(pid_str)})
            if p: return p
        except: pass

        # ── 2. بحث بـ _id كـ string (لمنتجات مثل cgpt_main_xxx) ──
        p = db.products.find_one({'_id': pid_str})
        if p: return p

        # ── 3. بحث بـ _id كـ ObjectId أو كـ cgpt_main_xxx ──
        if len(pid_str) == 24:
            try:
                p = db.products.find_one({'_id': f"cgpt_main_{pid_str}"})
                if p: return p
                p = db.products.find_one({'_id': ObjectId(pid_str)})
                if p: return p
            except: pass

        # ── 4. بحث إضافي: ربما pid_str هو الجزء الرقمي من id مخزن كـ float ──
        if '.' not in pid_str:
            try:
                p = db.products.find_one({'id': finite_float(pid_str + '.0')})
                if p: return p
            except: pass

        # ── 5. آخر محاولة: منتج ChatGPT من cgpt_products ──
        #    (يدعم البادئة cgpt_ وأيضاً الـ hex المجرّd بلا بادئة)
        clean_hex = pid_str.replace("cgpt_main_", "").replace("cgpt_", "")
        if "_" in clean_hex:
            clean_hex = clean_hex.split("_")[0]
        if len(clean_hex) == 24:
            try:
                cgpt_p = db.cgpt_products.find_one({'_id': ObjectId(clean_hex)})
                if cgpt_p:
                    return {
                        '_id': f"cgpt_main_{clean_hex}",
                        'name_ar': cgpt_p.get('name', 'ChatGPT'),
                        'name_en': cgpt_p.get('name_en', cgpt_p.get('name', 'ChatGPT')),
                        'desc_ar': cgpt_p.get('desc', ''),
                        'desc_en': cgpt_p.get('desc_en', cgpt_p.get('desc', '')),
                        'custom_emoji_id': cgpt_p.get('custom_emoji_id'),
                        'product_type': 'cgpt_main',
                        'cgpt_product_id': clean_hex,
                        'cgpt_pinned': True,
                        'is_manual': False,
                        'is_hidden': False,
                        'price': 0,
                        'btn_style': 'primary',
                    }
            except: pass
    except Exception as fp_err:
        logger.error(f"find_product error for pid={pid}: {fp_err}")
    return None

def get_product_stock_count(pid):
    try:
        # Resolve the product first to get the correct 'id' field if it exists
        p = find_product(pid)
        if p and p.get('id'):
            pid_str = str(p.get('id'))
        else:
            pid_str = str(pid)

        queries = [{'product_id': pid_str}]
        if pid_str.isdigit(): queries.append({'product_id': int(pid_str)})
        try: queries.append({'product_id': finite_float(pid_str)})
        except: pass
        return db.product_stock.count_documents({'$or': queries, 'is_sold': False})
    except: return 0

