@bot.callback_query_handler(func=lambda call: call.data == "cancel_deposit")
def cancel_deposit_handler(call):
    """يلغي عملية الإيداع الجارية"""
    bot.answer_callback_query(call.id)
    uid = call.from_user.id
    l = get_lang(uid)
    
    # نحذف الـ pending
    db.pending_deposits.update_many(
        {'user_id': uid, 'status': 'pending'},
        {'$set': {'status': 'cancelled'}}
    )
    
    # 🔓 فك القفل
    unlock_deposit(uid)
    
    # مسح أي step handler معلّق
    try:
        bot.clear_step_handler_by_chat_id(chat_id=uid)
    except: pass
    
    if l == 'ar':
        msg = "❌ <b>تم إلغاء عملية الإيداع.</b>\n\nيمكنك البدء من جديد في أي وقت."
    else:
        msg = "❌ <b>Deposit cancelled.</b>\n\nYou can start a new deposit anytime."
    
    try:
        bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    except: pass
    bot.send_message(uid, msg, parse_mode="HTML")


def is_coin_hidden(coin_key):
    """هل هذه العملة/الطريقة مخفية من قائمة الإيداع؟ (تبقى في لوحة الأدمن)."""
    try:
        v = get_setting(f'hide_coin_{coin_key}', '')
        return str(v) == '1'
    except Exception:
        return False


def set_coin_hidden(coin_key, hidden):
    """يخفي أو يُظهر عملة في قائمة الإيداع."""
    try:
        db.settings.update_one({'key': f'hide_coin_{coin_key}'},
                               {'$set': {'value': '1' if hidden else '0'}}, upsert=True)
        return True
    except Exception:
        return False


