def _dep_bybit_start_flow(uid, method):
    """يبدأ تدفّق الدفع الفعلي (UID أولاً أو المبلغ مباشرة)."""
    bot.clear_step_handler_by_chat_id(chat_id=uid)
    try:
        db.users.update_one(
            {'user_id': uid},
            {'$set': {'deposit_locked': True,
                      'deposit_lock_expires': int(time.time()) + 30 * 60}},
            upsert=True
        )
    except Exception:
        pass

    # 🆔 طريقة UID: نطلب أولاً رقم UID الخاص بالمستخدم في Bybit (للمطابقة المزدوجة)
    if method == 'UID':
        markup = InlineKeyboardMarkup()
        markup.add(_make_btn(get_text(uid, 'dep_btn_cancel'), callback_data="cancel_deposit"))
        msg = bot.send_message(uid, get_text(uid, 'bybit_ask_uid'),
                               parse_mode="HTML", reply_markup=markup)
        bot.register_next_step_handler(msg, ask_bybit_sender_uid, method)
        return

    msg_text = get_text(uid, 'dep_prompt_amount', _bybit_method_label(uid, method))
    markup = InlineKeyboardMarkup()
    markup.add(_make_btn(get_text(uid, 'dep_btn_cancel'), callback_data="cancel_deposit"))
    msg = bot.send_message(uid, msg_text, parse_mode="HTML", reply_markup=markup)
    bot.register_next_step_handler(msg, ask_bybit_deposit_amount, method, None)


@safe_next_step
def ask_bybit_sender_uid(message, method):
    """يستلم UID المستخدم في Bybit، يتحقق من صيغته، ثم يطلب المبلغ."""
    uid = message.from_user.id
    if is_user_banned(uid):
        return
    l = get_lang(uid)

    def _retry(err=None):
        send_payment_lock_warning(uid, l)
        markup = InlineKeyboardMarkup()
        markup.add(_make_btn(get_text(uid, 'dep_btn_cancel'), callback_data="cancel_deposit"))
        txt = (err + "\n\n" if err else "") + get_text(uid, 'bybit_ask_uid')
        m = bot.send_message(uid, txt, parse_mode="HTML", reply_markup=markup)
        bot.register_next_step_handler(m, ask_bybit_sender_uid, method)

    if not message.text or message.text.startswith('/'):
        _retry(); return
    sender_uid = message.text.strip()
    # UID في Bybit أرقام فقط (عادة 6-12 خانة)
    if not re.fullmatch(r'\d{5,15}', sender_uid):
        _retry(bil(uid, "❌ UID غير صالح — أرقام فقط (من ملفك في Bybit).",
                        "❌ Invalid UID — digits only (from your Bybit profile).")); return

    # ننتقل لطلب المبلغ حاملين الـ sender_uid
    markup = InlineKeyboardMarkup()
    markup.add(_make_btn(get_text(uid, 'dep_btn_cancel'), callback_data="cancel_deposit"))
    msg = bot.send_message(uid, get_text(uid, 'dep_prompt_amount', _bybit_method_label(uid, method)),
                           parse_mode="HTML", reply_markup=markup)
    bot.register_next_step_handler(msg, ask_bybit_deposit_amount, method, sender_uid)


def _bybit_method_label(uid, method):
    l = get_lang(uid)
    if method == 'UID':
        return 'Bybit — UID' if l == 'en' else 'Bybit — تحويل داخلي'
    cfg = BYBIT_NETWORKS.get(method, {})
    return cfg.get('label_en' if l == 'en' else 'label_ar', f"Bybit {method}")


def _bybit_coin_of(method):
    if method == 'UID':
        return 'BYBIT_UID'
    return BYBIT_NETWORKS.get(method, {}).get('coin', 'BYBIT_UID')


@safe_next_step
def ask_bybit_deposit_amount(message, method, sender_uid=None):
    """يستلم المبلغ ويعرض شاشة Bybit مع المبلغ الفريد."""
    uid = message.from_user.id
    if is_user_banned(uid):
        return
    l = get_lang(uid)
    coin = _bybit_coin_of(method)

    def _retry():
        send_payment_lock_warning(uid, l)
        markup = InlineKeyboardMarkup()
        markup.add(_make_btn(get_text(uid, 'dep_btn_cancel'), callback_data="cancel_deposit"))
        m = bot.send_message(uid, get_text(uid, 'dep_prompt_amount',
                                           _bybit_method_label(uid, method)),
                             parse_mode="HTML", reply_markup=markup)
        bot.register_next_step_handler(m, ask_bybit_deposit_amount, method, sender_uid)

    if not message.text or message.text.startswith('/'):
        _retry(); return
    try:
        base_amount = finite_float(message.text.strip().replace(',', '.').replace('$', ''))
    except ValueError:
        _retry(); return

    if base_amount < 1:
        bot.send_message(uid, get_text(uid, 'dep_err_min'), parse_mode="HTML"); _retry(); return
    if base_amount > 10000:
        bot.send_message(uid, get_text(uid, 'dep_err_max'), parse_mode="HTML"); _retry(); return

    unique_amount = generate_unique_amount_for_user(base_amount, uid, coin)
    pending = register_pending_deposit(uid, base_amount, unique_amount, coin, sender_uid=sender_uid)
    if not pending:
        bot.send_message(uid, get_text(uid, 'dep_err_general'), parse_mode="HTML")
        return

    markup = InlineKeyboardMarkup(row_width=2)

    if method == 'UID':
        _k, _s, bybit_uid, _b = _bybit_creds()
        # نص قابل للتعديل: {0}=UID  {1}=المبلغ الفريد  {2}=آيدي المستخدم
        msg_text = get_text(uid, 'bybit_msg_uid', html.escape(bybit_uid),
                            f"{unique_amount:.6f}", str(uid))
        # صف 1: المبلغ + الـ UID (اللي يحوّل له)
        markup.add(
            _copy_button(get_text(uid, 'dep_btn_copy_amount'), f"{unique_amount:.6f}"),
            _copy_button(get_text(uid, 'bybit_btn_copy_uid'), bybit_uid)
        )
    else:
        addr = _bybit_net_address(method)
        # نص قابل للتعديل: {0}=اسم الشبكة  {1}=العنوان  {2}=المبلغ الفريد
        msg_text = get_text(uid, 'bybit_msg_net', _bybit_method_label(uid, method),
                            html.escape(addr), f"{unique_amount:.6f}")
        # صف 1: المبلغ + العنوان
        markup.add(
            _copy_button(get_text(uid, 'dep_btn_copy_amount'), f"{unique_amount:.6f}"),
            _copy_button(get_text(uid, 'dep_btn_copy_wallet'), addr)
        )

    # صف 2: نسخ آيدي المستخدم (يُكتب في الملاحظة) — في الطريقتين
    markup.add(_copy_button(get_text(uid, 'dep_btn_copy_id'), str(uid)))
    # صف 3: فحص الدفع فوراً (بدل انتظار الفحص التلقائي)
    markup.add(_make_btn(get_text(uid, 'dep_btn_check'),
                         callback_data=f"bybit_check_{uid}"))
    markup.add(_make_btn(get_text(uid, 'dep_btn_cancel'), callback_data="cancel_deposit"))
    bot.send_message(uid, msg_text, parse_mode="HTML", reply_markup=markup)


@bot.callback_query_handler(func=lambda call: call.data.startswith("bybit_check_"))
def bybit_check_payment(call):
    """🔍 يفحص Bybit فوراً لما المستخدم يضغط زر (فحص الدفع)."""
    uid = call.from_user.id
    try:
        bot.answer_callback_query(
            call.id,
            "⏳ جاري الفحص..." if get_lang(uid) == 'ar' else "⏳ Checking..."
        )
    except Exception:
        pass
    if is_user_banned(uid):
        return

    # 🛡 المستخدم يفحص إيداعه هو فقط
    try:
        target = int(call.data.replace("bybit_check_", ""))
        if target != uid:
            return
    except Exception:
        return

    # 🛡 حد بسيط لمنع الضغط المتكرر (كل 10 ثوانٍ)
    try:
        last = _BYBIT_CHECK_COOLDOWN.get(uid, 0)
        if time.time() - last < 10:
            bot.answer_callback_query(
                call.id,
                "⏳ انتظر قليلاً..." if get_lang(uid) == 'ar' else "⏳ Please wait...",
                show_alert=False
            )
            return
        _BYBIT_CHECK_COOLDOWN[uid] = time.time()
    except Exception:
        pass

    checking = bot.send_message(
        uid,
        bil(uid, "🔍 <b>جاري فحص Bybit...</b>\nانتظر ثوانٍ.",
                 "🔍 <b>Checking Bybit...</b>\nPlease wait."),
        parse_mode="HTML"
    )

    # نلتقط الرصيد قبل الفحص لنعرف هل أُضيف شيء
    try:
        before = finite_float((db.users.find_one({'user_id': uid}) or {}).get('balance', 0) or 0)
    except Exception:
        before = 0.0

    try:
        check_bybit_auto()
    except Exception as e:
        logger.error(f"bybit manual check err: {e}")

    try:
        after = finite_float((db.users.find_one({'user_id': uid}) or {}).get('balance', 0) or 0)
    except Exception:
        after = before

    try:
        bot.delete_message(uid, checking.message_id)
    except Exception:
        pass

    if after > before:
        # نجح — رسالة التأكيد وصلت أصلاً من auto_credit_from_pending
        return

    bot.send_message(
        uid,
        bil(uid,
            "⏳ <b>لم نستلم تحويلك بعد.</b>\n\n"
            "• تأكد أن المبلغ <b>مطابق تماماً</b> للمبلغ المعروض\n"
            "• التحويل الداخلي فوري، وإيداع الشبكة يحتاج تأكيدات\n\n"
            "<i>سيُضاف الرصيد تلقائياً فور وصوله.</i>",
            "⏳ <b>Your transfer hasn't arrived yet.</b>\n\n"
            "• Make sure the amount matches <b>exactly</b>\n"
            "• Internal transfers are instant; network deposits need confirmations\n\n"
            "<i>Your balance will be credited automatically once received.</i>"),
        parse_mode="HTML"
    )


# ------------------------------------------------------------
# 🔎 أدوات الأدمن
# ------------------------------------------------------------
def admin_search_bybit_tx(query):
    """يبحث عن معاملة Bybit بأي معرّف (TxID/OrderId/...) لفحص المعاملات."""
    if not bybit_is_configured():
        return None
    q = str(query).strip().lower()
    if len(q) < 6:          # 🛡 استعلام قصير جداً يطابق أي شيء — نرفضه
        return None
    for kind, label in (('internal', 'Bybit (UID Transfer)'), ('onchain', 'Bybit (Network)')):
        try:
            rows = get_bybit_deposits(kind=kind, limit=200)   # وسّعنا من 50
        except Exception:
            continue
        for row in rows or []:
            # 🔧 نطابق ضد كل المعرّفات المحتملة في السجل، مو حقلاً واحداً
            candidates = _bybit_all_ids(row)
            main_tx = _bybit_row_txid(row) or (candidates[0] if candidates else '')
            matched = False
            for cand in candidates:
                t = cand.strip().lower()
                if (q == t) or (len(q) >= 12 and q in t) or (len(t) >= 12 and t in q) \
                   or _tx_hash_matches(query, cand):
                    matched = True
                    main_tx = cand
                    break
            if not matched:
                continue
            usd, coin_name = _bybit_row_usd(row)
            return {
                'hash': main_tx, 'label': f"🟠 {label}", 'coin': coin_name,
                'amount_usd': usd, 'crypto_amount': finite_float(row.get('amount') or 0),
                'when': _bybit_row_time_ms(row), 'note': _bybit_row_note(row), 'kind': kind,
            }
    return None


def _cgpt_get_user_subscriptions(uid):
    """يجمع كل اشتراكات ChatGPT النشطة لعميل عبر كل الحسابات.
    يرجّع قائمة: [{email, account_id, account_email, expires_at, remaining_days, product_id}]"""
    subs = []
    now = _dt_mod.datetime.now()
    for doc in _cgpt_all_accounts():
        acc_id = str(doc.get('_id'))
        try:
            idata = db.cgpt_invites_data.find_one({'_id': acc_id})
            invites = (idata.get('data', {}).get('invites', {})) if idata else {}
        except Exception:
            invites = {}
        acc_email = doc.get('data', {}).get('user', {}).get('email', doc.get('name', 'حساب'))
        for email, info in invites.items():
            if info.get('status') != 'active':
                continue
            if str(info.get('telegram_uid')) != str(uid):
                continue
            try:
                exp = _dt_mod.datetime.fromisoformat(info['expires_at'])
                if exp <= now:
                    continue
                remaining = exp - now
                rem_days = remaining.days
                rem_hours = int(remaining.seconds / 3600)
                subs.append({
                    'email': email, 'account_id': acc_id, 'account_email': acc_email,
                    'expires_at': info['expires_at'], 'remaining_days': rem_days,
                    'remaining_hours': rem_hours, 'product_id': info.get('product_id', ''),
                })
            except Exception:
                pass
    return subs


