@bot.callback_query_handler(func=lambda call: call.data.startswith("extadd_"))
@admin_required
def ext_add_new_product(call):
    """يضيف منتج API جديد (بعد إشعار الأدمن) — يجلبه ويسجّله."""
    try: bot.answer_callback_query(call.id, "⏳ جاري الإضافة...")
    except Exception: pass
    raw = call.data.replace("extadd_", "")
    sid, _, ext_id = raw.partition('_')
    try:
        store = db.ext_stores.find_one({'_id': ObjectId(sid)})
    except Exception:
        store = None
    if not store:
        bot.send_message(call.message.chat.id, "❌ المتجر غير موجود.")
        return
    # نجلب بيانات المنتج من المعلّق أو من API مباشرة
    pending = db.ext_pending_new.find_one({'store_id': sid, 'ext_id': ext_id})
    p = None
    if pending and pending.get('raw'):
        p = pending['raw']
    else:
        data = _ext_api_get(store, '/products')
        prods = _ext_parse_products(data)
        for pr in prods:
            if str(pr.get('id', pr.get('product_id', ''))) == ext_id:
                p = pr
                break
    if not p:
        bot.send_message(call.message.chat.id, "❌ لم أجد المنتج في المتجر.")
        return
    # نسجّله بنفس منطق المزامنة
    _f = _ext_extract_fields(p)
    base_price = _f['sell_price']
    cost_price = _f['cost_price']
    name = _f['name']
    desc = _f['desc']
    emoji_id = _f['emoji_id']
    emoji_char = _f['emoji_char']
    stock = _f['stock']
    # 🆕 يرث نسبة المتجر الافتراضية
    _def_mt = store.get('default_markup_type', 'percent') if isinstance(store, dict) else 'percent'
    _def_mv = store.get('default_markup_value', 0) if isinstance(store, dict) else 0
    _cost0 = finite_float(cost_price or base_price or 0)
    _sell0 = _ext_compute_sell_price(_cost0, _def_mt, _def_mv)
    doc = {
        'store_id': sid, 'ext_id': ext_id, 'name': name,
        'desc': desc, 'desc_text': p.get('description_text', ''),
        'base_price': finite_float(base_price or 0), 'cost_price': finite_float(cost_price or 0),
        'emoji_id': emoji_id, 'emoji_char': emoji_char, 'stock': stock,
        'markup_type': _def_mt, 'markup_value': _def_mv,
        'sell_price': _sell0, 'hidden': False, 'raw': p,
    }
    res = db.ext_products.insert_one(doc)
    if not doc.get('hidden'):
        threading.Thread(target=_ext_broadcast_new_product,args=({**doc,'_id':res.inserted_id},),daemon=True).start()
    db.ext_pending_new.delete_many({'store_id': sid, 'ext_id': ext_id})
    # برودكاست منتج جديد — للعملاء عبر API + لمستخدمي البوت
    try:
        _emit_event('product.created', {
            'product_id': f"ext_{res.inserted_id}",
            'name_ar': name, 'name_en': name,
            'price': finite_float(base_price or 0),
            'is_manual': False, 'is_hidden': False, 'stock': stock,
            'description': desc, 'emoji': emoji_char, 'emoji_custom_id': emoji_id,
            'source': 'external_api',
        }, product_id=f"ext_{res.inserted_id}")
    except Exception:
        pass
    try:
        bot.edit_message_text(
            f"✅ أُضيف المنتج: {html.escape(name)}\nافتح المتجر لتسعيره وإظهاره.",
            call.message.chat.id, call.message.message_id, parse_mode="HTML")
    except Exception:
        bot.send_message(call.message.chat.id, f"✅ أُضيف: {html.escape(name)}", parse_mode="HTML")


@bot.callback_query_handler(func=lambda call: call.data.startswith("extign_"))
@admin_required
def ext_ignore_new_product(call):
    """يتجاهل منتج API جديد (لا يضيفه، ويمنع تكر1ر الإشعار)."""
    raw = call.data.replace("extign_", "")
    sid, _, ext_id = raw.partition('_')
    try:
        # نبقيه في المعلّق كـ "متجاهَل" لمنع تكرار الإشعار
        db.ext_pending_new.update_one(
            {'store_id': sid, 'ext_id': ext_id},
            {'$set': {'ignored': True}}, upsert=True)
    except Exception:
        pass
    try:
        bot.answer_callback_query(call.id, "🚫 تم التجاهل")
        bot.edit_message_text("🚫 تم تجاهل المنتج.", call.message.chat.id,
                              call.message.message_id)
    except Exception:
        pass


@bot.callback_query_handler(func=lambda call: call.data.startswith("ext_raw_"))
@admin_required
def ext_raw_preview(call):
    """يعرض الرد الخام لأول منتج من API — لمعرفة أسماء الحقول الحقيقية."""
    try: bot.answer_callback_query(call.id, "🔬 جاري الجلب...")
    except Exception: pass
    sid = call.data.replace("ext_raw_", "")
    try:
        store = db.ext_stores.find_one({'_id': ObjectId(sid)})
    except Exception:
        store = None
    if not store:
        bot.send_message(call.message.chat.id, "❌ المتجر غير موجود.")
        return
    data = _ext_api_get(store, '/products')
    prods = _ext_parse_products(data)
    if not prods:
        # نعرض تشخيصاً مفصّلاً يكشف سبب الفشل
        diag = _ext_api_diagnose(store)
        bot.send_message(call.message.chat.id,
            f"⚠️ <b>لم أجلب منتجات — التشخيص:</b>\n\n"
            f"<code>{html.escape(diag[:3500])}</code>",
            parse_mode="HTML")
        return
    first = prods[0]
    keys = list(first.keys()) if isinstance(first, dict) else []
    import json as _json
    sample = _json.dumps(first, ensure_ascii=False, indent=1)[:1500]
    bot.send_message(call.message.chat.id,
        f"🔬 <b>أول منتج من API:</b>\n\n"
        f"<b>الحقول المتاحة:</b>\n<code>{html.escape(', '.join(keys))}</code>\n\n"
        f"<b>المحتوى:</b>\n<code>{html.escape(sample)}</code>",
        parse_mode="HTML")


@bot.callback_query_handler(func=lambda call: call.data.startswith("ext_sync_"))
@admin_required
def ext_sync_products(call):
    from operations import product_list
    bot.answer_callback_query(call.id, '🔄 جاري التحديث...')
    sid = call.data.removeprefix('ext_sync_')
    store = db.ext_stores.find_one({'_id': ObjectId(sid)})
    if not store: raise ShopError('المتجر غير موجود.')
    products = product_list(_ext_api_get(store, '/products'))
    if products is None: raise ShopError('تعذر قراءة المنتجات؛ احتُفظ بالمخزون السابق.')
    with _ops.sync_lock:
        _ops.sync_products(sid, products)
    bot.send_message(call.from_user.id, '✅ تم تحديث الأسعار والمخزون بصمت. تنبيهات عودة التوفر تدخل الملخص المجمع.')


@bot.callback_query_handler(func=lambda call: call.data.startswith("ext_pick_"))
@admin_required
def ext_pick_products(call):
    """يعرض منتجات المتجر من API للاختيار (صفحات + تلوين أخضر للمختار)."""
    try: bot.answer_callback_query(call.id)
    except Exception: pass
    raw = call.data.replace("ext_pick_", "")
    sid, _, page_s = raw.rpartition('_')
    page = int(page_s) if page_s.isdigit() else 0
    try:
        store = db.ext_stores.find_one({'_id': ObjectId(sid)})
    except Exception:
        store = None
    if not store:
        bot.send_message(call.message.chat.id, "❌ المتجر غير موجود.")
        return
    # نجلب المنتجات من API (نخزّنها مؤقتاً لتفادي جلب متكرر)
    data = _ext_api_get(store, '/products')
    prods = _ext_parse_products(data)
    if not prods:
        bot.send_message(call.message.chat.id, "⚠️ لم أجلب منتجات من المتجر.")
        return
    # نحفظ قائمة الاختيار المؤقتة (المختارة) في المتجr
    picked = set(store.get('_pick_selected', []))
    PER = 15
    total = len(prods)
    start = page * PER
    page_prods = prods[start:start + PER]

    markup = InlineKeyboardMarkup(row_width=1)
    for p in page_prods:
        _f = _ext_extract_fields(p)
        ext_id = _f['ext_id']
        if not ext_id:
            continue
        is_picked = ext_id in picked
        mark = "🟢" if is_picked else "⚪"
        nm = _f['name'][:28]
        bkw = {'text': f"{mark} {nm} — ${_f['sell_price']:.2f}",
               'callback_data': f"ext_ptog_{sid}_{ext_id}_{page}",
               'style': 'success' if is_picked else 'secondary'}
        if _f['emoji_id']:
            bkw['icon_custom_emoji_id'] = _f['emoji_id']
        markup.add(CustomInlineButton(**bkw))
    # تنقّل الصفحات
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton("⬅️", callback_data=f"ext_pick_{sid}_{page-1}"))
    total_pages = (total + PER - 1) // PER
    if total_pages > 1:
        nav.append(InlineKeyboardButton(f"{page+1}/{total_pages}", callback_data="noop"))
    if start + PER < total:
        nav.append(InlineKeyboardButton("➡️", callback_data=f"ext_pick_{sid}_{page+1}"))
    if nav:
        markup.row(*nav)
    # أزرd التحكم
    markup.add(
        InlineKeyboardButton("✅ اختيار الكل", callback_data=f"ext_pall_{sid}_{page}"),
        InlineKeyboardButton("❌ إلغd الكل", callback_data=f"ext_pnone_{sid}_{page}")
    )
    markup.add(InlineKeyboardButton(f"✔️ موافق — أضف المختارة ({len(picked)})",
               callback_data=f"ext_pok_{sid}"))
    markup.add(InlineKeyboardButton("🔙 رجوع", callback_data=f"ext_store_{sid}"))
    txt = (f"🎯 <b>اختيار منتجات للإضافة</b>\n\n"
           f"اضغط المنتج ليصير 🟢 (مختار). المختار فقط سيُضاف.\n\n"
           f"📦 المجموع: {total} | 🟢 مختار: {len(picked)}")
    try:
        bot.edit_message_text(txt, call.message.chat.id, call.message.message_id,
                              parse_mode="HTML", reply_markup=markup)
    except Exception:
        bot.send_message(call.message.chat.id, txt, parse_mode="HTML", reply_markup=markup)


@bot.callback_query_handler(func=lambda call: call.data.startswith("ext_ptog_"))
@admin_required
def ext_pick_toggle(call):
    """يبدّل اختيار منتج (أخضر/رمادي)."""
    raw = call.data.replace("ext_ptog_", "")
    parts = raw.rsplit('_', 2)  # sid, ext_id, page
    if len(parts) != 3:
        return
    sid, ext_id, page = parts[0], parts[1], parts[2]
    try:
        store = db.ext_stores.find_one({'_id': ObjectId(sid)})
    except Exception:
        store = None
    if not store:
        return
    picked = set(store.get('_pick_selected', []))
    if ext_id in picked:
        picked.discard(ext_id)
    else:
        picked.add(ext_id)
    db.ext_stores.update_one({'_id': ObjectId(sid)},
                             {'$set': {'_pick_selected': list(picked)}})
    try: bot.answer_callback_query(call.id)
    except Exception: pass
    call.data = f"ext_pick_{sid}_{page}"
    ext_pick_products(call)


